import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {

    static char[] addOne(char[] num) {
        int n = num.length;
        char[] res = new char[n];
        int carry = 1;
        for (int i = n - 1; i >= 0; i--) {
            int d = (num[i] - '0') + carry;
            if (d >= 10) {
                res[i] = (char) ('0' + (d - 10));
                carry = 1;
            } else {
                res[i] = (char) ('0' + d);
                carry = 0;
            }
        }
        if (carry == 1) {
            char[] extended = new char[n + 1];
            extended[0] = '1';
            System.arraycopy(res, 0, extended, 1, n);
            return extended;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        if (line == null) return;

        int n = Integer.parseInt(line.trim());
        char[] s = new char[n];
        int count = 0;

        while (count < n) {
            String l = reader.readLine();
            if (l == null) break;
            StringTokenizer tokenizer = new StringTokenizer(l);
            while (tokenizer.hasMoreTokens() && count < n) {
                s[count++] = tokenizer.nextToken().charAt(0);
            }
        }

        for (int l = 1; l <= n; l++) {
            char[] cur = new char[l];
            System.arraycopy(s, 0, cur, 0, l);

            int idx = l;
            boolean ok = true;

            while (idx < n) {
                cur = addOne(cur);
                int len = cur.length;
                if (idx + len > n) {
                    ok = false;
                    break;
                }
                for (int j = 0; j < len; j++) {
                    if (s[idx + j] != cur[j]) {
                        ok = false;
                        break;
                    }
                }
                if (!ok) break;
                idx += len;
            }

            if (ok && idx == n) {
                System.out.println(new String(s, 0, l));
                return;
            }
        }
    }
}
