const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextToken() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        const start = pos;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            pos++;
        }
        return input.slice(start, pos);
    }

    const nStr = nextToken();
    if (!nStr) return;
    const N = parseInt(nStr, 10);

    let digits = '';
    for (let i = 0; i < N; i++) {
        digits += nextToken();
    }

    // O primeiro dígito não pode ser '0' para A >= 1
    // Testamos todos os comprimentos possíveis L de A, de 1 até N.
    // O primeiro L que gerar exatamente a sequência de dígitos fornece o menor valor de A.
    for (let L = 1; L <= N; L++) {
        const aStr = digits.slice(0, L);
        let curr = BigInt(aStr);
        let idx = 0;
        let matched = true;

        while (idx < N) {
            const s = curr.toString();
            if (idx + s.length > N) {
                matched = false;
                break;
            }
            if (digits.startsWith(s, idx)) {
                idx += s.length;
                curr++;
            } else {
                matched = false;
                break;
            }
        }

        if (matched && idx === N) {
            console.log(aStr);
            return;
        }
    }
}

main();
